<?php
declare(strict_types=1);
namespace App\Controllers; use App\Core\Request;use App\Core\View;use App\Core\Response;use App\Core\Database;use App\Core\Session;use App\Middleware\PermissionMiddleware;
final class SettingsController {public function index(Request $r):void{PermissionMiddleware::require('settings.view');$rows=Database::connection()->query('SELECT * FROM settings ORDER BY setting_key')->fetchAll();$settings=[];foreach($rows as $row)$settings[$row['setting_key']]=$row['setting_value'];View::render('settings/index',compact('settings'));}public function save(Request $r):void{PermissionMiddleware::require('settings.edit');verify_csrf();$pdo=Database::connection();foreach(['app_name','currency','date_format','timezone','pagination_size','budget_warning_thresholds'] as $k){if($r->input($k)!==null){$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()');$s->execute([$k,$r->input($k)]);}}Session::flash('success','Settings saved.');Response::redirect('/settings');}}
